36	/**
37	 * Extracts the human-readable invite message from the invite's defaultsPayload,
38	 * if present. Returns null when the payload does not contain a non-empty string
39	 * at the `agentMessage` key.
40	 */
41	export function extractInviteMessage(invite: {
42	  defaultsPayload: unknown;
43	}): string | null {
44	  const raw = invite.defaultsPayload;
45	  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return null;
46	  const msg = (raw as Record<string, unknown>).agentMessage;
47	  if (typeof msg !== "string") return null;
48	  const trimmed = msg.trim();
49	  return trimmed.length ? trimmed : null;
50	}
